    export default defineRenderer((graphic) => {
  const c = graphic.canvas.getContext("2d");
  if (c === null) throw new Error("Canvas 2D is unavailable");
  const FAR = 4000;
  return {
    render() {
      const i = graphic.inputs, { width, height } = graphic.size, pr = graphic.pixelRatio, s = i.scale.value;
      const hw = i.screenWidth.value / 2 + i.bezel.value + i.band.value, hh = i.screenHeight.value / 2 + i.bezel.value + i.band.value;
      const R = i.radius.value + i.bezel.value + i.band.value;
      const lay = i.lay.value * Math.PI / 180, yaw = i.yaw.value * Math.PI / 180, tan = Math.tan(lay);
      const { r, g, b } = i.shade.value, k = i.strength.value;
      for (const [reach, drop, blur, alpha] of [[i.depth.value + i.lift.value, 54, 120, 0.2], [i.depth.value * 0.9, 10, 26, 0.3]]) {
        c.save();
        c.shadowColor = "rgb(" + r * 255 + " " + g * 255 + " " + b * 255 + " / " + Math.min(1, alpha * k) + ")";
        c.shadowBlur = blur * s * pr;
        c.shadowOffsetX = FAR * pr;
        c.shadowOffsetY = drop * s * pr;
        c.translate(width / 2 - FAR, height / 2);
        c.rotate(yaw);
        c.scale(s, s);
        const d = reach * tan;
        c.beginPath();
        c.roundRect(-hw + d * Math.sin(yaw), -hh + d * Math.cos(yaw), 2 * hw, 2 * hh, R);
        c.fillStyle = "#000";
        c.fill();
        c.restore();
      }
    },
  };
});


